"use client";

import React, { useState } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import Footer from "@/components/common/Footer";

const SetupPassword: React.FC = () => {
  const searchParams = useSearchParams();
  const router = useRouter();
  const token = searchParams.get("token");

  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const handleSetupPassword = async (e: React.FormEvent) => {
    e.preventDefault();

    if (password.length < 6) {
      setError("Password must be at least 6 characters.");
      return;
    }

    if (password !== confirmPassword) {
      setError("Passwords do not match.");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/v1/auth/setup-password?token=${token}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password }),
      });

      if (!response.ok) {
        throw new Error("Failed to set up password. The link may be expired.");
      }

      setSuccess(true);
      setTimeout(() => router.push("/auth/login"), 3000); 
    } catch (err: any) {
      setError(err.message || "An error occurred.");
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    router.push("/auth/login");
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-light-gray">
      <h1 className="text-4xl font-bold text-red-600 mb-4 text-center">Set Up Your Password</h1>

      <p className="text-lg text-gray-600 mb-6 text-center">
        Please set your new password to complete the account setup process. Your password must be at least 6 characters long.
      </p>

      {success ? (
        <p className="text-green-600 font-semibold">
          Password set successfully! Redirecting to login...
        </p>
      ) : (
        <form onSubmit={handleSetupPassword} className="w-full max-w-xs">
          <input
            type="password"
            placeholder="New Password"
            className="border border-gray-300 text-black rounded-lg p-2 w-full mb-4"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="Confirm Password"
            className="border border-gray-300 text-black rounded-lg p-2 w-full mb-4"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            required
          />
          <div className="flex justify-center gap-4">
            <button
              type="button"
              onClick={handleCancel}
              className="bg-gray-300 text-black font-semibold py-2 px-4 rounded-full hover:bg-gray-500 transition duration-300"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="bg-gray-300 text-black font-semibold py-2 px-4 rounded-full hover:bg-gray-500 transition duration-300"
              disabled={loading}
            >
              {loading ? "Setting Password..." : "Confirm"}
            </button>
          </div>
        </form>
      )}

      {error && <p className="text-red-500 font-semibold mt-2">{error}</p>}
      <Footer />
    </div>
  );
};

export default SetupPassword;
